alter table public.church_assets add column if not exists asset_status text not null default 'active';
alter table public.church_assets add column if not exists depreciation_method text not null default 'straight_line';
alter table public.church_assets add column if not exists useful_life_months integer;
alter table public.church_assets add column if not exists salvage_value numeric(14,2) not null default 0;
alter table public.church_assets add column if not exists depreciation_start_date date;
alter table public.church_assets add column if not exists accumulated_depreciation numeric(14,2) not null default 0;
alter table public.church_assets add column if not exists asset_account_id uuid references public.chart_of_accounts(id);
alter table public.church_assets add column if not exists accumulated_depreciation_account_id uuid references public.chart_of_accounts(id);
alter table public.church_assets add column if not exists depreciation_expense_account_id uuid references public.chart_of_accounts(id);
alter table public.church_assets add column if not exists disposal_gain_account_id uuid references public.chart_of_accounts(id);
alter table public.church_assets add column if not exists disposal_loss_account_id uuid references public.chart_of_accounts(id);
alter table public.church_assets add column if not exists disposal_cash_account_id uuid references public.financial_accounts(id);
alter table public.church_assets add column if not exists disposal_date date;
alter table public.church_assets add column if not exists disposal_proceeds numeric(14,2);
alter table public.church_assets add column if not exists disposal_gain_loss numeric(14,2);
alter table public.church_assets add column if not exists disposal_notes text;
alter table public.church_assets add constraint church_assets_status_valid check(asset_status in ('active','disposed','retired')) not valid;
alter table public.church_assets add constraint church_assets_depreciation_method_valid check(depreciation_method in ('straight_line','none')) not valid;
alter table public.church_assets add constraint church_assets_depreciation_values_valid check((useful_life_months is null or useful_life_months>0) and salvage_value>=0 and accumulated_depreciation>=0) not valid;
create table public.asset_depreciation_entries(id uuid primary key default gen_random_uuid(),church_id uuid not null references public.churches(id) on delete cascade,asset_id uuid not null references public.church_assets(id) on delete restrict,period_end date not null,amount numeric(14,2) not null check(amount>0),journal_entry_id uuid not null references public.journal_entries(id) on delete restrict,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(asset_id,period_end));
alter table public.asset_depreciation_entries enable row level security;
create policy asset_depreciation_entries_permission_all on public.asset_depreciation_entries for all to authenticated using(private.has_church_permission(church_id,'assets','view')) with check(private.has_church_permission(church_id,'assets','edit'));
